UPDATE warehouse.stock_take_items
SET counted_quantity   = #{countedQuantity},
    surplus_unit_price = #{surplusUnitPrice}
WHERE id = #{itemId}
AND stock_take_id = #{stockTakeId}

UPDATE warehouse.stock_takes
SET status    = 'CANCELLED',
    closed_at = NOW(),
    closed_by = #{userId}
WHERE id = #{id}
AND status = 'OPEN'
